//go:build arm64 && !purego

// ===========================================================================
// NEON Size-32768 Mixed-Radix (Radix-4 + Radix-2) FFT Kernels for ARM64 (complex64)
// ===========================================================================
//
// Size 32768 = 2 * 4^7, mixed-radix algorithm (digit-reversal permutation
// with radices [4,4,4,4,4,4,4,2], then 8192 radix-4 butterflies without
// twiddles, then radix-4 twiddle stages, then a final radix-2 stage):
//   Stage 1: 8192 radix-4 butterflies (no twiddles), span=4
//   Stage 2: radix-4 with twiddles, 2048 blocks x 4 butterflies, span=16
//   Stage 3: radix-4 with twiddles, 512 blocks x 16 butterflies, span=64
//   Stage 4: radix-4 with twiddles, 128 blocks x 64 butterflies, span=256
//   Stage 5: radix-4 with twiddles, 32 blocks x 256 butterflies, span=1024
//   Stage 6: radix-4 with twiddles, 8 blocks x 1024 butterflies, span=4096
//   Stage 7: radix-4 with twiddles, 2 blocks x 4096 butterflies, span=16384
//   Stage 8: radix-2 with twiddles, 16384 butterflies, twiddle step=1
//
// Each complex64 element is 8 bytes (real f32 + imag f32). NEON idioms follow
// neon_f32_size2048_mixed24.s (scalar FMOVS/FADDS/FSUBS/FMULS/FNEGS on the
// D/S register file), scaled from n=2048=2*4^5 to n=32768=2*4^7 (two more
// radix-4 twiddle stages: step=4096 and step=16384).
//
// ===========================================================================

#include "textflag.h"

// Forward transform, size 32768, complex64, mixed radix (radix-4 x7, radix-2).
// func ForwardNEONSize32768Radix4Then2Complex64Asm(dst, src, twiddle, scratch []complex64) bool
TEXT ·ForwardNEONSize32768Radix4Then2Complex64Asm(SB), NOSPLIT, $0-97
	MOVD dst+0(FP), R8
	MOVD src+24(FP), R9
	MOVD twiddle+48(FP), R10
	MOVD scratch+72(FP), R11
	MOVD src_len+32(FP), R13

	CMP  $32768, R13
	BNE  neon32768m24_return_false

	MOVD dst_len+8(FP), R0
	CMP  $32768, R0
	BLT  neon32768m24_return_false

	MOVD twiddle_len+56(FP), R0
	CMP  $32768, R0
	BLT  neon32768m24_return_false

	MOVD scratch_len+80(FP), R0
	CMP  $32768, R0
	BLT  neon32768m24_return_false

	MOVD $bitrev_size32768_mixed24<>(SB), R12

	MOVD R8, R20
	CMP  R8, R9
	BNE  neon32768m24_use_dst
	MOVD R11, R8

neon32768m24_use_dst:
	// Bit-reversal permutation (mixed-radix 2/4)
	MOVD $0, R0

neon32768m24_bitrev_loop:
	CMP  $32768, R0
	BGE  neon32768m24_stage1

	LSL  $3, R0, R1
	ADD  R12, R1, R1
	MOVD (R1), R2

	LSL  $3, R2, R3
	ADD  R9, R3, R3
	MOVD (R3), R4

	LSL  $3, R0, R3
	ADD  R8, R3, R3
	MOVD R4, (R3)

	ADD  $1, R0, R0
	B    neon32768m24_bitrev_loop

neon32768m24_stage1:
	// Stage 1: 8192 radix-4 butterflies (no twiddles)
	MOVD $0, R14

neon32768m24_stage1_loop:
	CMP  $32768, R14
	BGE  neon32768m24_stage2

	LSL  $3, R14, R1
	ADD  R8, R1, R1

	FMOVS 0(R1), F0
	FMOVS 4(R1), F1
	FMOVS 8(R1), F2
	FMOVS 12(R1), F3
	FMOVS 16(R1), F4
	FMOVS 20(R1), F5
	FMOVS 24(R1), F6
	FMOVS 28(R1), F7

	FADDS F4, F0, F8
	FADDS F5, F1, F9
	FSUBS F4, F0, F10
	FSUBS F5, F1, F11

	FADDS F6, F2, F12
	FADDS F7, F3, F13
	FSUBS F6, F2, F14
	FSUBS F7, F3, F15

	FADDS F12, F8, F16
	FADDS F13, F9, F17
	FSUBS F12, F8, F18
	FSUBS F13, F9, F19

	FMOVS F15, F20
	FNEGS F14, F21
	FADDS F20, F10, F22
	FADDS F21, F11, F23

	FNEGS F15, F24
	FMOVS F14, F25
	FADDS F24, F10, F26
	FADDS F25, F11, F27

	FMOVS F16, 0(R1)
	FMOVS F17, 4(R1)
	FMOVS F22, 8(R1)
	FMOVS F23, 12(R1)
	FMOVS F18, 16(R1)
	FMOVS F19, 20(R1)
	FMOVS F26, 24(R1)
	FMOVS F27, 28(R1)

	ADD  $4, R14, R14
	B    neon32768m24_stage1_loop

neon32768m24_stage2:
	// Stage: radix-4, step=16, blocks=2048, butterflies/block=4, twiddle stride=2048
	MOVD $0, R14

neon32768m24_stage2_base:
	CMP  $32768, R14
	BGE  neon32768m24_stage3

	MOVD $0, R15

neon32768m24_stage2_j:
	CMP  $4, R15
	BGE  neon32768m24_stage2_next

	ADD  R14, R15, R0       // idx0
	ADD  $4, R0, R1        // idx1
	ADD  $8, R0, R2        // idx2
	ADD  $12, R0, R3        // idx3

	LSL  $11, R15, R4        // j*2048
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F0
	FMOVS 4(R5), F1

	LSL  $12, R15, R4        // j*4096
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F2
	FMOVS 4(R5), F3

	LSL  $11, R15, R6        // j*2048
	LSL  $12, R15, R4        // j*4096
	ADD  R4, R6, R6         // j*6144
	LSL  $3, R6, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F4
	FMOVS 4(R5), F5

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F6
	FMOVS 4(R7), F7

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F8
	FMOVS 4(R7), F9

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F10
	FMOVS 4(R7), F11

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F12
	FMOVS 4(R7), F13

	// a1 = w1 * a1
	FMULS F0, F8, F14
	FMULS F1, F9, F15
	FSUBS F15, F14, F14
	FMULS F0, F9, F15
	FMULS F1, F8, F16
	FADDS F16, F15, F15

	// a2 = w2 * a2
	FMULS F2, F10, F16
	FMULS F3, F11, F17
	FSUBS F17, F16, F16
	FMULS F2, F11, F17
	FMULS F3, F10, F18
	FADDS F18, F17, F17

	// a3 = w3 * a3
	FMULS F4, F12, F18
	FMULS F5, F13, F19
	FSUBS F19, F18, F18
	FMULS F4, F13, F19
	FMULS F5, F12, F20
	FADDS F20, F19, F19

	FADDS F16, F6, F20
	FADDS F17, F7, F21
	FSUBS F16, F6, F22
	FSUBS F17, F7, F23

	FADDS F18, F14, F24
	FADDS F19, F15, F25
	FSUBS F18, F14, F26
	FSUBS F19, F15, F27

	// out0 = t0 + t2
	FADDS F24, F20, F28
	FADDS F25, F21, F29
	// out2 = t0 - t2
	FSUBS F24, F20, F30
	FSUBS F25, F21, F31

	// out1 = t1 + mulNegI(t3)
	FADDS F27, F22, F6
	FSUBS F26, F23, F7
	// out3 = t1 + mulI(t3)
	FSUBS F27, F22, F8
	FADDS F26, F23, F9

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS F28, 0(R7)
	FMOVS F29, 4(R7)

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS F6, 0(R7)
	FMOVS F7, 4(R7)

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS F30, 0(R7)
	FMOVS F31, 4(R7)

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS F8, 0(R7)
	FMOVS F9, 4(R7)

	ADD  $1, R15, R15
	B    neon32768m24_stage2_j

neon32768m24_stage2_next:
	ADD  $16, R14, R14
	B    neon32768m24_stage2_base

neon32768m24_stage3:
	// Stage: radix-4, step=64, blocks=512, butterflies/block=16, twiddle stride=512
	MOVD $0, R14

neon32768m24_stage3_base:
	CMP  $32768, R14
	BGE  neon32768m24_stage4

	MOVD $0, R15

neon32768m24_stage3_j:
	CMP  $16, R15
	BGE  neon32768m24_stage3_next

	ADD  R14, R15, R0       // idx0
	ADD  $16, R0, R1        // idx1
	ADD  $32, R0, R2        // idx2
	ADD  $48, R0, R3        // idx3

	LSL  $9, R15, R4        // j*512
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F0
	FMOVS 4(R5), F1

	LSL  $10, R15, R4        // j*1024
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F2
	FMOVS 4(R5), F3

	LSL  $9, R15, R6        // j*512
	LSL  $10, R15, R4        // j*1024
	ADD  R4, R6, R6         // j*1536
	LSL  $3, R6, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F4
	FMOVS 4(R5), F5

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F6
	FMOVS 4(R7), F7

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F8
	FMOVS 4(R7), F9

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F10
	FMOVS 4(R7), F11

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F12
	FMOVS 4(R7), F13

	// a1 = w1 * a1
	FMULS F0, F8, F14
	FMULS F1, F9, F15
	FSUBS F15, F14, F14
	FMULS F0, F9, F15
	FMULS F1, F8, F16
	FADDS F16, F15, F15

	// a2 = w2 * a2
	FMULS F2, F10, F16
	FMULS F3, F11, F17
	FSUBS F17, F16, F16
	FMULS F2, F11, F17
	FMULS F3, F10, F18
	FADDS F18, F17, F17

	// a3 = w3 * a3
	FMULS F4, F12, F18
	FMULS F5, F13, F19
	FSUBS F19, F18, F18
	FMULS F4, F13, F19
	FMULS F5, F12, F20
	FADDS F20, F19, F19

	FADDS F16, F6, F20
	FADDS F17, F7, F21
	FSUBS F16, F6, F22
	FSUBS F17, F7, F23

	FADDS F18, F14, F24
	FADDS F19, F15, F25
	FSUBS F18, F14, F26
	FSUBS F19, F15, F27

	// out0 = t0 + t2
	FADDS F24, F20, F28
	FADDS F25, F21, F29
	// out2 = t0 - t2
	FSUBS F24, F20, F30
	FSUBS F25, F21, F31

	// out1 = t1 + mulNegI(t3)
	FADDS F27, F22, F6
	FSUBS F26, F23, F7
	// out3 = t1 + mulI(t3)
	FSUBS F27, F22, F8
	FADDS F26, F23, F9

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS F28, 0(R7)
	FMOVS F29, 4(R7)

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS F6, 0(R7)
	FMOVS F7, 4(R7)

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS F30, 0(R7)
	FMOVS F31, 4(R7)

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS F8, 0(R7)
	FMOVS F9, 4(R7)

	ADD  $1, R15, R15
	B    neon32768m24_stage3_j

neon32768m24_stage3_next:
	ADD  $64, R14, R14
	B    neon32768m24_stage3_base

neon32768m24_stage4:
	// Stage: radix-4, step=256, blocks=128, butterflies/block=64, twiddle stride=128
	MOVD $0, R14

neon32768m24_stage4_base:
	CMP  $32768, R14
	BGE  neon32768m24_stage5

	MOVD $0, R15

neon32768m24_stage4_j:
	CMP  $64, R15
	BGE  neon32768m24_stage4_next

	ADD  R14, R15, R0       // idx0
	ADD  $64, R0, R1        // idx1
	ADD  $128, R0, R2        // idx2
	ADD  $192, R0, R3        // idx3

	LSL  $7, R15, R4        // j*128
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F0
	FMOVS 4(R5), F1

	LSL  $8, R15, R4        // j*256
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F2
	FMOVS 4(R5), F3

	LSL  $7, R15, R6        // j*128
	LSL  $8, R15, R4        // j*256
	ADD  R4, R6, R6         // j*384
	LSL  $3, R6, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F4
	FMOVS 4(R5), F5

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F6
	FMOVS 4(R7), F7

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F8
	FMOVS 4(R7), F9

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F10
	FMOVS 4(R7), F11

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F12
	FMOVS 4(R7), F13

	// a1 = w1 * a1
	FMULS F0, F8, F14
	FMULS F1, F9, F15
	FSUBS F15, F14, F14
	FMULS F0, F9, F15
	FMULS F1, F8, F16
	FADDS F16, F15, F15

	// a2 = w2 * a2
	FMULS F2, F10, F16
	FMULS F3, F11, F17
	FSUBS F17, F16, F16
	FMULS F2, F11, F17
	FMULS F3, F10, F18
	FADDS F18, F17, F17

	// a3 = w3 * a3
	FMULS F4, F12, F18
	FMULS F5, F13, F19
	FSUBS F19, F18, F18
	FMULS F4, F13, F19
	FMULS F5, F12, F20
	FADDS F20, F19, F19

	FADDS F16, F6, F20
	FADDS F17, F7, F21
	FSUBS F16, F6, F22
	FSUBS F17, F7, F23

	FADDS F18, F14, F24
	FADDS F19, F15, F25
	FSUBS F18, F14, F26
	FSUBS F19, F15, F27

	// out0 = t0 + t2
	FADDS F24, F20, F28
	FADDS F25, F21, F29
	// out2 = t0 - t2
	FSUBS F24, F20, F30
	FSUBS F25, F21, F31

	// out1 = t1 + mulNegI(t3)
	FADDS F27, F22, F6
	FSUBS F26, F23, F7
	// out3 = t1 + mulI(t3)
	FSUBS F27, F22, F8
	FADDS F26, F23, F9

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS F28, 0(R7)
	FMOVS F29, 4(R7)

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS F6, 0(R7)
	FMOVS F7, 4(R7)

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS F30, 0(R7)
	FMOVS F31, 4(R7)

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS F8, 0(R7)
	FMOVS F9, 4(R7)

	ADD  $1, R15, R15
	B    neon32768m24_stage4_j

neon32768m24_stage4_next:
	ADD  $256, R14, R14
	B    neon32768m24_stage4_base

neon32768m24_stage5:
	// Stage: radix-4, step=1024, blocks=32, butterflies/block=256, twiddle stride=32
	MOVD $0, R14

neon32768m24_stage5_base:
	CMP  $32768, R14
	BGE  neon32768m24_stage6

	MOVD $0, R15

neon32768m24_stage5_j:
	CMP  $256, R15
	BGE  neon32768m24_stage5_next

	ADD  R14, R15, R0       // idx0
	ADD  $256, R0, R1        // idx1
	ADD  $512, R0, R2        // idx2
	ADD  $768, R0, R3        // idx3

	LSL  $5, R15, R4        // j*32
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F0
	FMOVS 4(R5), F1

	LSL  $6, R15, R4        // j*64
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F2
	FMOVS 4(R5), F3

	LSL  $5, R15, R6        // j*32
	LSL  $6, R15, R4        // j*64
	ADD  R4, R6, R6         // j*96
	LSL  $3, R6, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F4
	FMOVS 4(R5), F5

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F6
	FMOVS 4(R7), F7

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F8
	FMOVS 4(R7), F9

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F10
	FMOVS 4(R7), F11

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS 0(R7), F12
	FMOVS 4(R7), F13

	// a1 = w1 * a1
	FMULS F0, F8, F14
	FMULS F1, F9, F15
	FSUBS F15, F14, F14
	FMULS F0, F9, F15
	FMULS F1, F8, F16
	FADDS F16, F15, F15

	// a2 = w2 * a2
	FMULS F2, F10, F16
	FMULS F3, F11, F17
	FSUBS F17, F16, F16
	FMULS F2, F11, F17
	FMULS F3, F10, F18
	FADDS F18, F17, F17

	// a3 = w3 * a3
	FMULS F4, F12, F18
	FMULS F5, F13, F19
	FSUBS F19, F18, F18
	FMULS F4, F13, F19
	FMULS F5, F12, F20
	FADDS F20, F19, F19

	FADDS F16, F6, F20
	FADDS F17, F7, F21
	FSUBS F16, F6, F22
	FSUBS F17, F7, F23

	FADDS F18, F14, F24
	FADDS F19, F15, F25
	FSUBS F18, F14, F26
	FSUBS F19, F15, F27

	// out0 = t0 + t2
	FADDS F24, F20, F28
	FADDS F25, F21, F29
	// out2 = t0 - t2
	FSUBS F24, F20, F30
	FSUBS F25, F21, F31

	// out1 = t1 + mulNegI(t3)
	FADDS F27, F22, F6
	FSUBS F26, F23, F7
	// out3 = t1 + mulI(t3)
	FSUBS F27, F22, F8
	FADDS F26, F23, F9

	LSL  $3, R0, R7
	ADD  R8, R7, R7
	FMOVS F28, 0(R7)
	FMOVS F29, 4(R7)

	LSL  $3, R1, R7
	ADD  R8, R7, R7
	FMOVS F6, 0(R7)
	FMOVS F7, 4(R7)

	LSL  $3, R2, R7
	ADD  R8, R7, R7
	FMOVS F30, 0(R7)
	FMOVS F31, 4(R7)

	LSL  $3, R3, R7
	ADD  R8, R7, R7
	FMOVS F8, 0(R7)
	FMOVS F9, 4(R7)

	ADD  $1, R15, R15
	B    neon32768m24_stage5_j

neon32768m24_stage5_next:
	ADD  $1024, R14, R14
	B    neon32768m24_stage5_base

neon32768m24_stage6:
	// Stage: radix-4, step=4096, blocks=8, butterflies/block=1024, twiddle stride=8
	MOVD $0, R14

neon32768m24_stage6_base:
	CMP  $32768, R14
	BGE  neon32768m24_stage7

	MOVD $0, R15

neon32768m24_stage6_j:
	CMP  $1024, R15
	BGE  neon32768m24_stage6_next

	ADD  R14, R15, R0       // idx0
	ADD  $1024, R0, R1        // idx1
	ADD  $2048, R0, R2        // idx2
	ADD  $3072, R0, R3        // idx3

	LSL  $3, R15, R4        // j*8
	LSL  $3, R4, R5
	ADD  R10, R5, R5
	FMOVS 0(R5), F0
	FMOVS 4(R5), F1

